import{_ as n,o as a,c as r,a2 as t}from"./chunks/framework.CtQGab4e.js";const h=JSON.parse('{"title":"Wat kan (nog) niet","description":"","frontmatter":{},"headers":[],"relativePath":"grenzen.md","filePath":"grenzen.md"}'),o={name:"grenzen.md"};function l(i,e,d,g,s,k){return a(),r("div",null,[...e[0]||(e[0]=[t('<h1 id="wat-kan-nog-niet" tabindex="-1">Wat kan (nog) niet <a class="header-anchor" href="#wat-kan-nog-niet" aria-label="Permalink to &quot;Wat kan (nog) niet&quot;">​</a></h1><p>Wat nog niet kan, en hoe je daar nu het beste mee omgaat. Komt iets later wel, dan staat het in <a href="./wat-is-er-nieuw.html">Wat is er nieuw</a>.</p><h2 id="daken" tabindex="-1">Daken <a class="header-anchor" href="#daken" aria-label="Permalink to &quot;Daken&quot;">​</a></h2><ul><li><strong>Dakkapellen</strong> teken je met de knop Dakkapel, zie <a href="./hoe-teken-ik/dakkapel.html">Dakkapel</a>. Nog niet mogelijk: een dakkapel op een gebroken kap (mansarde), twee dakkapellen die elkaar raken, en een dakkapel die tegen een gevel zonder dak aan loopt (lessenaarsdak). De 3D-server geeft dan een melding.</li><li><strong>Gebogen of getoogde daken.</strong> Niet mogelijk. De 3D-server maakt daken uit rechte dakvlakken: zadeldak, schilddak, lessenaarsdak, mansarde- of gebroken kap en wolfskap.</li></ul><h2 id="verdiepingen" tabindex="-1">Verdiepingen <a class="header-anchor" href="#verdiepingen" aria-label="Permalink to &quot;Verdiepingen&quot;">​</a></h2><ul><li><strong>Souterrains.</strong> Een half verdiepte verdieping wordt nog niet goed ondersteund. </li><li><strong>Een onverwarmde kelder</strong> onder een deel van de begane grond kan wel, zonder eigen verdieping: zie <a href="./plattegrond/vlakken.html#kelder">Kelder</a>.</li></ul><h2 id="vloeren" tabindex="-1">Vloeren <a class="header-anchor" href="#vloeren" aria-label="Permalink to &quot;Vloeren&quot;">​</a></h2><ul><li><strong>Begrenzing van de vloer</strong> (grond, kruipruimte, buiten) stel je in de tekening nog niet in. De 3D-server rekent wel de m² vloer uit. Klopt de begrenzing niet, voeg dan in het 3D-paneel zelf een vloer toe en verwijder de oude, zie <a href="./plattegrond/constructies.html#constructie-toevoegen">Constructie toevoegen</a>. Een vloer boven een <a href="./plattegrond/vlakken.html#kelder">kelder</a> krijgt wel vanzelf de begrenzing onverwarmde kelder.</li></ul><h2 id="_3d-paneel-en-export" tabindex="-1">3D-paneel en export <a class="header-anchor" href="#_3d-paneel-en-export" aria-label="Permalink to &quot;3D-paneel en export&quot;">​</a></h2><ul><li><strong>Correcties en opnieuw genereren.</strong> Bij een nieuw model vervallen je correcties, zie <a href="./plattegrond/3d-paneel.html#genereren">Genereren</a>.</li><li><strong>Interactieve weergave op de iPad.</strong> Draait niet in Bestanden; open hem op een computer.</li><li><strong>Je rekensoftware</strong> vul je nog met de hand in, op basis van <em>Berekeningen.txt</em> uit de <a href="./plattegrond/export-3d.html">export</a>.</li></ul>',10)])])}const u=n(o,[["render",l]]);export{h as __pageData,u as default};
